package com.coffeeshop.service;import com.coffeeshop.dto.RefundCommands;import com.coffeeshop.model.RefundModels;import com.coffeeshop.repository.RefundRepository;import java.math.*;import java.util.*;public final class RefundService{private final RefundRepository repository;public RefundService(RefundRepository r){repository=Objects.requireNonNull(r);}public RefundModels.Catalog catalog(){return repository.load();}public long refund(RefundModels.Payment p,BigDecimal amount,String reason,String reference,String notes,long user){Objects.requireNonNull(p);if(user<=0)throw new IllegalArgumentException("An authenticated user is required.");if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Refund amount must be greater than zero.");amount=amount.setScale(4,RoundingMode.HALF_UP);if(p.remaining().signum()<=0||"REFUNDED".equals(p.status())||"VOIDED".equals(p.status()))throw new IllegalStateException("This payment is not refundable.");if(amount.compareTo(p.remaining())>0)throw new IllegalArgumentException("Refund amount exceeds the remaining refundable amount.");return repository.refund(new RefundCommands.Create(p.id(),amount,required(reason,500,"Reason"),optional(reference,100,"Reference"),optional(notes,1000,"Notes"),user,p.version()));}private static String required(String v,int m,String n){if(v==null||v.isBlank())throw new IllegalArgumentException(n+" is required.");String x=v.trim();if(x.length()>m)throw new IllegalArgumentException(n+" is too long.");return x;}private static String optional(String v,int m,String n){return v==null||v.isBlank()?null:required(v,m,n);}}
